/**
 * Shared starter modal card population (Kanto + regional resonance).
 */

import { REGIONAL_RESONANCE } from '../../constants/balance/regionalResonance.ts';
import { POKEMON_PRIMARY_TYPES, POKEMON_SECONDARY_TYPES, TYPES } from '../../constants/core.ts';
import type { GameRuntime } from '../types/game.js';
import { getPokemonSpriteUrl } from '../ui/utils.ts';
import { coerceStr } from './coerceStr.ts';
import { getRegions } from './regionsRuntime.ts';

export type StarterSlot = 'grass' | 'fire' | 'water';

export interface StarterSpeciesSet {
    grass: string;
    fire: string;
    water: string;
}

export const KANTO_STARTERS: StarterSpeciesSet = {
    grass: 'Bulbasaur',
    fire: 'Charmander',
    water: 'Squirtle',
};

const SLOT_DESC_KEYS: Record<StarterSlot, string> = {
    grass: 'modal.starterGrassDesc',
    fire: 'modal.starterFireDesc',
    water: 'modal.starterWaterDesc',
};

const SLOT_DOM: Record<StarterSlot, {
    nameId: string;
    dataArg: string;
}> = {
    grass: {
        nameId: 'starterGrassNameLabel',
        dataArg: 'grass',
    },
    fire: {
        nameId: 'starterFireNameLabel',
        dataArg: 'fire',
    },
    water: {
        nameId: 'starterWaterNameLabel',
        dataArg: 'water',
    },
};

export interface StarterCardFields {
    localizedName: string;
    spriteUrl: string;
    primaryType: string;
    secondaryType: string | null;
    descriptionKey: string;
    primaryTypeLabelKey: string;
    secondaryTypeLabelKey: string | null;
}

export function getStarterModalSpeciesByRegion(regionId?: string | null): StarterSpeciesSet {
    const region = String(regionId || '').toLowerCase();
    const regional = REGIONAL_RESONANCE.startersByRegion[region];
    if (regional) {
        return { grass: regional.grass, fire: regional.fire, water: regional.water };
    }
    return { ...KANTO_STARTERS };
}

export type StarterModalContext = {
    isRegional: boolean;
    regionId: string | null;
    species: StarterSpeciesSet;
};

function readPendingRegionalStarterRegion(game: GameRuntime): string | null {
    const pending = (game as GameRuntime & { _pendingRegionalStarterRegion?: string })
        ._pendingRegionalStarterRegion;
    if (typeof pending !== 'string' || !pending) return null;
    return pending.toLowerCase();
}

export function resolveStarterModalContext(game: GameRuntime): StarterModalContext {
    const pendingRegion = readPendingRegionalStarterRegion(game);

    if (!pendingRegion) {
        return { isRegional: false, regionId: null, species: { ...KANTO_STARTERS } };
    }

    if (!REGIONAL_RESONANCE.startersByRegion[pendingRegion]) {
        return { isRegional: false, regionId: null, species: { ...KANTO_STARTERS } };
    }

    return {
        isRegional: true,
        regionId: pendingRegion,
        species: getStarterModalSpeciesByRegion(pendingRegion),
    };
}

export function applyStarterModalLanguage(game: GameRuntime): void {
    const ctx = resolveStarterModalContext(game);
    const isEn = typeof game.normalizeLanguage === 'function'
        && game.normalizeLanguage(game.language) === 'en';

    const speakerEl = document.getElementById('starterSpeakerLabel');
    if (speakerEl) speakerEl.textContent = isEn ? 'Professor Chen' : 'Professeur Chen';

    const titleEl = document.getElementById('starterTitleLabel');
    const subtitleEl = document.getElementById('starterSubtitleLabel');

    if (ctx.isRegional && ctx.regionId) {
        const regionName = getRegionDisplayName(ctx.regionId);
        if (titleEl && typeof game.t === 'function') {
            titleEl.textContent = game.t('resonance.modalTitle', { region: regionName });
        }
        applyRegionalResonancePanel(game, ctx.regionId);
        setStarterResonancePanelVisible(true);
        applyStarterModalCards(game, ctx.species);
        return;
    }

    if (titleEl && typeof game.t === 'function') {
        titleEl.textContent = game.t('modal.starterTitle');
    }
    if (subtitleEl && typeof game.t === 'function') {
        subtitleEl.textContent = game.t('modal.starterSubtitle');
        subtitleEl.hidden = false;
    }
    setStarterResonancePanelVisible(false);
    applyStarterModalCards(game, ctx.species);
}

function resolvePrimaryType(game: GameRuntime, species: string): string {
    if (typeof game.findTypeForPokemon === 'function') {
        return game.findTypeForPokemon(species);
    }
    return POKEMON_PRIMARY_TYPES[species] || TYPES.NORMAL;
}

export function buildStarterCardFields(
    game: GameRuntime,
    species: string,
    slot: StarterSlot,
): StarterCardFields {
    const primaryType = resolvePrimaryType(game, species);
    const secondaryType = POKEMON_SECONDARY_TYPES[species] ?? null;
    const localizedName =
        typeof game.getLocalizedPokemonName === 'function'
            ? game.getLocalizedPokemonName(species)
            : species;

    return {
        localizedName,
        spriteUrl: getPokemonSpriteUrl(species, false, false),
        primaryType,
        secondaryType,
        descriptionKey: SLOT_DESC_KEYS[slot],
        primaryTypeLabelKey: `types.${primaryType}`,
        secondaryTypeLabelKey: secondaryType ? `types.${secondaryType}` : null,
    };
}

function applyCard(
    game: GameRuntime,
    modal: HTMLElement,
    species: string,
    slot: StarterSlot,
): void {
    const fields = buildStarterCardFields(game, species, slot);
    const dom = SLOT_DOM[slot];
    const translate = (key: string) =>
        (typeof game.t === 'function' ? game.t(key) : key);

    const nameEl = document.getElementById(dom.nameId);
    if (nameEl) nameEl.textContent = fields.localizedName;

    const btn = modal.querySelector(`[data-action="selectStarter"][data-arg="${dom.dataArg}"]`);
    const img = btn?.querySelector('.starter-sprite') as HTMLImageElement | null;
    if (img) {
        img.src = fields.spriteUrl;
        img.alt = fields.localizedName;
    }

    if (btn instanceof HTMLButtonElement && typeof game.t === 'function') {
        const typeLabels = [translate(fields.primaryTypeLabelKey)];
        if (fields.secondaryTypeLabelKey) {
            typeLabels.push(translate(fields.secondaryTypeLabelKey));
        }
        const description = translate(fields.descriptionKey);
        btn.title = `${fields.localizedName} — ${typeLabels.join(' / ')}. ${description}`;
        btn.setAttribute('aria-label', btn.title);
    }
}

export function applyStarterModalCards(game: GameRuntime, starters: StarterSpeciesSet): void {
    const modal = document.getElementById('starterModal');
    if (!modal) return;
    applyCard(game, modal, starters.grass, 'grass');
    applyCard(game, modal, starters.fire, 'fire');
    applyCard(game, modal, starters.water, 'water');
}

export function getRegionDisplayName(regionId: string): string {
    const rid = String(regionId || 'kanto');
    const r = getRegions()[rid];
    if (r && r.name) return coerceStr(r.name, rid);
    return rid;
}

const RESONANCE_PANEL_IDS = {
    panel: 'starterResonancePanel',
    lead: 'starterResonanceLead',
    bulletAnchors: 'starterResonanceBulletAnchors',
    bulletCap: 'starterResonanceBulletCap',
    bulletCatchUp: 'starterResonanceBulletCatchUp',
    bulletEnd: 'starterResonanceBulletEnd',
    cta: 'starterResonanceCta',
} as const;

const RESONANCE_PANEL_I18N = {
    lead: 'resonance.modalLead',
    bulletAnchors: 'resonance.modalBulletAnchors',
    bulletCap: 'resonance.modalBulletCap',
    bulletCatchUp: 'resonance.modalBulletCatchUp',
    bulletEnd: 'resonance.modalBulletEnd',
    cta: 'resonance.modalChooseStarter',
} as const;

function setTextById(id: string, text: string): void {
    const el = document.getElementById(id);
    if (el) el.textContent = text;
}

export function setStarterResonancePanelVisible(visible: boolean): void {
    const panel = document.getElementById(RESONANCE_PANEL_IDS.panel);
    if (panel) panel.hidden = !visible;

    const subtitle = document.getElementById('starterSubtitleLabel');
    if (subtitle) subtitle.hidden = visible;

    const modal = document.getElementById('starterModal');
    if (modal) modal.classList.toggle('starter-modal--regional', visible);
}

export function applyRegionalResonancePanel(game: GameRuntime, regionId: string): void {
    const regionName = getRegionDisplayName(regionId);
    const vars = { region: regionName };
    const translate = (key: string) =>
        (typeof game.t === 'function' ? game.t(key, vars) : key);

    setTextById(RESONANCE_PANEL_IDS.lead, translate(RESONANCE_PANEL_I18N.lead));
    setTextById(RESONANCE_PANEL_IDS.bulletAnchors, translate(RESONANCE_PANEL_I18N.bulletAnchors));
    setTextById(RESONANCE_PANEL_IDS.bulletCap, translate(RESONANCE_PANEL_I18N.bulletCap));
    setTextById(RESONANCE_PANEL_IDS.bulletCatchUp, translate(RESONANCE_PANEL_I18N.bulletCatchUp));
    setTextById(RESONANCE_PANEL_IDS.bulletEnd, translate(RESONANCE_PANEL_I18N.bulletEnd));
    setTextById(RESONANCE_PANEL_IDS.cta, translate(RESONANCE_PANEL_I18N.cta));
}
