import type { GameRuntime } from '../types/game.js';
import type { ArenaPanelUiSnapshot, ArenaSnapshot } from '../bus/snapshots.js';
import { publish } from '../bus/pub.js';
import { GameEventType as Evt } from '../bus/events.js';
import { arenaSnapshotWouldChange } from '../stores/arenaSnapshotDiff.js';
import { ARENAS, ACCOUNT_TALENTS, ZONES } from '@snapshot/arena';
import {
  getBadgeSpriteUrl,
  getLeagueBadgeFallbackLabel,
  getLeagueBadgeSpriteUrl,
  isLeagueBadgeKey,
} from '../../constants/badgeSprites.ts';
import { getRegionDisplayName } from './starterModalPresentation.ts';
import { buildEliteFourTrainerPreviews } from './eliteFourTrainerPreview.ts';

const TRAINER_CARD_REGION_ORDER = [
  'kanto',
  'johto',
  'hoenn',
  'sinnoh',
  'unova',
  'kalos',
  'alola',
] as const;

function arenaT(game: GameRuntime, key: string, fallback: string): string {
  if (typeof game.t === 'function') {
    const translated = game.t(key);
    if (translated && translated !== key) return translated;
  }
  return fallback;
}

export function buildArenaPanelUi(game: GameRuntime): ArenaPanelUiSnapshot {
  const language =
    game && typeof game.normalizeLanguage === 'function'
      ? game.normalizeLanguage(game.language)
      : 'fr';
  return {
    language,
    title: arenaT(game, 'arenas.title', 'Arènes de Combat'),
    subGyms: arenaT(game, 'arenas.subGyms', 'Arènes'),
    subElite: arenaT(game, 'arenas.subElite', 'Conseil des 4'),
    subTabsAriaLabel: arenaT(game, 'arenas.subTabsAriaLabel', 'Sous-sections arènes'),
  };
}

const KANTO_GYM_LEADER_SPRITES_BY_TALENT: Record<string, string> = {
  resilience: 'brock',
  vitality: 'misty',
  fortune: 'ltsurge',
  wisdom: 'erika',
  pension: 'koga',
  prestige: 'sabrina',
  power: 'blaine',
  master: 'giovanni',
};

function getKantoGymLeaderSpriteUrl(talentKey: string): string {
  const file = KANTO_GYM_LEADER_SPRITES_BY_TALENT[talentKey];
  if (!file) return '';
  return `https://play.pokemonshowdown.com/sprites/trainers/${file}.png`;
}

function asDisplayText(v: unknown): string {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean') return String(v);
  return '';
}

function escapeHtml(v: unknown): string {
  return asDisplayText(v)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function escTooltipAttr(v: unknown): string {
  return asDisplayText(v).replace(/&/g, '&amp;').replace(/"/g, '&quot;');
}

const GYM_BADGE_EFFECT_ORDER = [
  'hp_mult',
  'damage_mult',
  'damage_reduction',
  'life_steal',
  'crit_chance',
  'capture_chance',
  'pokedollars_mult',
  'exp_mult',
  'shard_chance',
  'egg_drop_chance',
  'respawn_delay_reduction',
  'expedition_time_reduction',
  'ultimate_charge_bonus',
  'pension_slots',
  'team_slot',
] as const;

const PERCENT_GYM_BADGE_EFFECTS = new Set([
  'hp_mult',
  'damage_mult',
  'damage_reduction',
  'life_steal',
  'crit_chance',
  'capture_chance',
  'pokedollars_mult',
  'exp_mult',
  'shard_chance',
  'egg_drop_chance',
  'expedition_time_reduction',
]);

export function collectRegionGymBadgeKeys(regionId: string): string[] {
  const regionArenas = Object.entries(ARENAS as Record<string, Record<string, unknown>>).filter(
    ([, arena]) => (asDisplayText(arena.regionId) || 'kanto') === regionId,
  );
  return regionArenas
    .map(([, a]) => asDisplayText(a.badge))
    .filter((key) => key && !isLeagueBadgeKey(key))
    .filter((key, idx, arr) => arr.indexOf(key) === idx);
}

export function aggregateOwnedRegionGymBadgeEffects(
  game: GameRuntime,
  regionId: string,
): Record<string, number> {
  const talents = ACCOUNT_TALENTS as Record<string, Record<string, unknown>>;
  const totals: Record<string, number> = {};
  collectRegionGymBadgeKeys(regionId).forEach((talentKey) => {
    if (!game.hasBadge(talentKey)) return;
    const talent = talents[talentKey];
    if (!talent) return;
    const effect = asDisplayText(talent.effect);
    if (!effect || effect.startsWith('league_')) return;
    const value = Number(talent.value);
    if (!Number.isFinite(value)) return;
    totals[effect] = (totals[effect] || 0) + value;
  });
  return totals;
}

function formatGymBadgeEffectSummaryValue(effect: string, total: number): string {
  if (PERCENT_GYM_BADGE_EFFECTS.has(effect)) {
    return (total * 100).toFixed(1);
  }
  if (effect === 'respawn_delay_reduction' || effect === 'ultimate_charge_bonus') {
    return String(Math.round(total));
  }
  if (effect === 'pension_slots' || effect === 'team_slot') {
    return String(Math.round(total));
  }
  return String(total);
}

export function buildRegionGymBadgeSummaryHtml(game: GameRuntime, regionId: string): string {
  const totals = aggregateOwnedRegionGymBadgeEffects(game, regionId);
  const title = escapeHtml(game.t('arenaUi.badgeRegionSummaryTitle'));
  const lines: string[] = [];

  GYM_BADGE_EFFECT_ORDER.forEach((effect) => {
    const total = totals[effect];
    if (total == null || Math.abs(total) < 1e-9) return;
    const value = formatGymBadgeEffectSummaryValue(effect, total);
    const line = game.t(`arenaUi.badgeEffectSummary_${effect}`, { value });
    if (line && line !== `arenaUi.badgeEffectSummary_${effect}`) {
      lines.push(`<div class="trainer-badge-region-summary-line">${escapeHtml(line)}</div>`);
    }
  });

  const body = lines.length
    ? lines.join('')
    : `<div class="trainer-badge-region-summary-line trainer-badge-region-summary-empty">${escapeHtml(game.t('arenaUi.badgeRegionSummaryEmpty'))}</div>`;

  return (
    `<div class="trainer-badge-region-summary">` +
    `<div class="trainer-badge-region-summary-title">${title}</div>` +
    body +
    `</div>`
  );
}

function getBadgeFallbackLabel(talentKey: string, talentName: string): string {
  if (isLeagueBadgeKey(talentKey)) return getLeagueBadgeFallbackLabel(talentKey);
  return String(talentName).replace(/[^A-Za-z0-9]/g, '').slice(0, 2).toUpperCase() || 'BD';
}

function getBadgeFallbackClass(talentKey: string): string {
  if (isLeagueBadgeKey(talentKey)) return 'trainer-badge-fallback trainer-badge-fallback--league';
  return 'trainer-badge-fallback';
}

function buildLeagueBadgeChipInnerHtml(talentKey: string, safeName: string): string {
  const fallbackLabel = escapeHtml(getLeagueBadgeFallbackLabel(talentKey));
  const leagueSpriteUrl = escapeHtml(getLeagueBadgeSpriteUrl(talentKey));
  if (leagueSpriteUrl) {
    return `<span class="trainer-badge-league-medal" aria-hidden="true"><img src="${leagueSpriteUrl}" class="trainer-badge-league-sprite" alt="${safeName}" onerror="this.style.display='none';var f=this.nextElementSibling;if(f)f.style.display='inline-flex';"><span class="trainer-badge-fallback trainer-badge-fallback--league" style="display:none;">${fallbackLabel}</span></span>`;
  }
  return `<span class="trainer-badge-league-medal" aria-hidden="true"><span class="trainer-badge-fallback trainer-badge-fallback--league">${fallbackLabel}</span></span>`;
}

export function buildBadgeChipHtml(
  game: GameRuntime,
  talentKey: string,
  talent: Record<string, unknown>,
): string {
  const talentName = game.getLocalizedAccountTalentName(talentKey, String(talent.name));
  const talentDesc = game.getLocalizedAccountTalentDescription(talentKey, String(talent.description));
  const safeName = escapeHtml(talentName);
  const safeDesc = escapeHtml(talentDesc);
  const fallbackLabel = escapeHtml(getBadgeFallbackLabel(talentKey, talentName));
  const tooltipDesc = escapeHtml(game.t('arenaUi.badgeEffect', { desc: safeDesc }));
  if (isLeagueBadgeKey(talentKey)) {
    const regionId = talentKey.replace(/^maitre_/, '');
    const tooltipBody =
      `<div>${escapeHtml(game.t('arenaUi.badgeEffect', { desc: talentDesc }))}</div>` +
      buildRegionGymBadgeSummaryHtml(game, regionId);
    return `<span class="trainer-badge-chip trainer-badge-chip--league" data-tooltip-title="${safeName}" data-tooltip-desc="${escTooltipAttr(tooltipBody)}">${buildLeagueBadgeChipInnerHtml(talentKey, safeName)}</span>`;
  }
  const badgeSpriteUrl = getBadgeSpriteUrl(talentKey);
  const fallbackClass = getBadgeFallbackClass(talentKey);
  return `<span class="trainer-badge-chip" data-tooltip-title="${safeName}" data-tooltip-desc="${tooltipDesc}">${
    badgeSpriteUrl
      ? `<img src="${badgeSpriteUrl}" class="arena-badge-sprite trainer-badge-sprite" alt="${safeName}" onerror="this.remove();">`
      : `<span class="${fallbackClass}" aria-hidden="true">${fallbackLabel}</span>`
  }</span>`;
}

function collectRegionBadgeTalentKeys(game: GameRuntime, regionId: string): string[] {
  const regionArenas = Object.entries(ARENAS as Record<string, Record<string, unknown>>).filter(
    ([, arena]) => (asDisplayText(arena.regionId) || 'kanto') === regionId,
  );
  const masterBadgeKey = game.getMasterBadgeForRegion(regionId);
  return [
    ...regionArenas
      .map(([, a]) => a.badge as string)
      .filter((key, idx, arr) => arr.indexOf(key) === idx),
    ...(masterBadgeKey && (ACCOUNT_TALENTS as Record<string, unknown>)[masterBadgeKey]
      ? [masterBadgeKey]
      : []),
  ];
}

export function buildTrainerBadgesHtml(
  game: GameRuntime,
  scope: 'region' | 'all',
  regionId?: string,
): { html: string; count: number } {
  const talents = ACCOUNT_TALENTS as Record<string, Record<string, unknown>>;
  let count = 0;
  let html = '';

  if (scope === 'region') {
    const activeRegionId = regionId || game.getCurrentRegionId();
    const orderedKeys = collectRegionBadgeTalentKeys(game, activeRegionId);
    orderedKeys.forEach((talentKey) => {
      const talent = talents[talentKey];
      if (!talent || !game.hasBadge(talentKey)) return;
      count++;
      html += buildBadgeChipHtml(game, talentKey, talent);
    });
  } else {
    TRAINER_CARD_REGION_ORDER.forEach((rid) => {
      const orderedKeys = collectRegionBadgeTalentKeys(game, rid);
      let regionHtml = '';
      let regionCount = 0;
      orderedKeys.forEach((talentKey) => {
        const talent = talents[talentKey];
        if (!talent || !game.hasBadge(talentKey)) return;
        regionCount++;
        regionHtml += buildBadgeChipHtml(game, talentKey, talent);
      });
      if (regionCount === 0) return;
      count += regionCount;
      const regionName = escapeHtml(getRegionDisplayName(rid));
      html += `<div class="trainer-card-region-section mastery-panel">
        <div class="trainer-card-region-title">${regionName}</div>
        <div class="trainer-badges-grid trainer-card-region-badges">${regionHtml}</div>
      </div>`;
    });
  }

  if (count === 0) {
    html = `<div class="trainer-card-empty">${game.t('arenaUi.noBadgeObtained')}</div>`;
  }

  return { html, count };
}

export function buildTrainerCardHtml(game: GameRuntime): string {
  const { html: badgesHtml, count } = buildTrainerBadgesHtml(game, 'all');
  const playerName = escapeHtml(
    typeof game.getPlayerProfileName === 'function' ? game.getPlayerProfileName() : 'Joueur',
  );
  const spriteUrl = escapeHtml(
    typeof game.getPlayerProfileSpriteUrl === 'function'
      ? game.getPlayerProfileSpriteUrl()
      : 'https://play.pokemonshowdown.com/sprites/trainers/red.png',
  );
  const cardTitle = escapeHtml(game.t('arenaUi.trainerCardTitle', { count }));
  return `<div class="mastery-trainer-card-header mastery-branch-header">
    <img src="${spriteUrl}" class="mastery-trainer-card-sprite" alt="${playerName}">
    <div class="mastery-trainer-card-meta">
      <div class="mastery-trainer-card-name">${playerName}</div>
      <div class="mastery-trainer-card-subtitle">${cardTitle}</div>
    </div>
  </div>
  <div class="mastery-trainer-card-badges">${badgesHtml}</div>`;
}

export function buildEliteFourPanelHtml(game: GameRuntime): string {
  const eliteArenaId = game.getEliteFourArenaIdForCurrentRegion();
  const eliteDef = game.getEliteFourDefinition(eliteArenaId) as Record<string, unknown> | null;
  if (!eliteDef) return '';

  const unlocked = game.isEliteFourUnlocked(eliteArenaId);
  const completed = game.hasBadge(String(eliteDef.rewardBadge));
  const inProgress = game.arenaState.active && game.arenaState.arenaId === eliteArenaId;

  return `
            <div class="upgrade-card ${completed ? 'arena-completed' : ''} ${!unlocked ? 'arena-locked' : ''}">
                <div class="upgrade-title">${asDisplayText(eliteDef.name)}</div>
                <div class="upgrade-description">
                    <p>${game.t('arenaUi.eliteRunDesc')}</p>
                </div>
                <div class="arena-reward-box">
                    <div class="arena-reward-title"><span>${game.t('arenaUi.eliteRewardTitle')}</span></div>
                    <div class="arena-reward-desc">${game.t('arenaUi.eliteRewardDesc')}</div>
                </div>
                <div class="arena-unlock-status">
                    ${inProgress ? game.t('arenaUi.eliteStatusInProgress') : (unlocked ? game.t('arenaUi.eliteStatusUnlocked') : game.t('arenaUi.eliteStatusLocked'))}
                </div>
                <button type="button" class="upgrade-btn" 
                    data-action="startArena" data-arg="${eliteArenaId}" 
                    ${!unlocked || inProgress ? 'disabled' : ''}>
                    ${inProgress ? game.t('arenaUi.eliteBtnInProgress') : (completed ? game.t('arenaUi.eliteBtnCompleted') : (unlocked ? game.t('arenaUi.eliteBtnStart') : game.t('arenaUi.eliteBtnLocked')))}
                </button>
            </div>
        `;
}

export function buildArenaPanelSnapshot(game: GameRuntime): ArenaSnapshot {
  const activeRegionId = game.getCurrentRegionId();
  const regionArenas = Object.entries(ARENAS as Record<string, Record<string, unknown>>).filter(
    ([, arena]) => (asDisplayText(arena.regionId) || 'kanto') === activeRegionId,
  );

  const { html: badgesHtml, count: trainerBadgesCount } = buildTrainerBadgesHtml(
    game,
    'region',
    activeRegionId,
  );
  const trainerCardTitle = game.t('arenaUi.trainerCardTitle', { count: trainerBadgesCount });

  let arenasHtml = '';
  regionArenas.forEach(([arenaId, arena]) => {
    const unlocked = game.isArenaUnlocked(arenaId);
    const completed = game.hasBadge(String(arena.badge));
    const talent = (ACCOUNT_TALENTS as Record<string, Record<string, unknown>>)[String(arena.badge)];
    const talentName = talent ? game.getLocalizedAccountTalentName(String(arena.badge), String(talent.name)) : '';
    const talentDesc = talent ? game.getLocalizedAccountTalentDescription(String(arena.badge), String(talent.description)) : '';
    const badgeSpriteUrl = getBadgeSpriteUrl(String(arena.badge));
    const championSpriteUrl = game.getArenaChampionSpriteUrl(arenaId) || getKantoGymLeaderSpriteUrl(String(arena.badge));
    const rewardBadgeHtml = badgeSpriteUrl
      ? `<img src="${badgeSpriteUrl}" class="arena-badge-sprite" alt="${talentName}" onerror="this.remove();">`
      : '';
    const requiredZone = (ZONES as Record<number, Record<string, unknown>>)[Number(arena.requiredZone)];
    const requiredZoneName = game.getLocalizedZoneName(
      Number(arena.requiredZone),
      requiredZone ? asDisplayText(requiredZone.name) : `Zone ${asDisplayText(arena.requiredZone)}`,
    );
    const reqBadgeKey = arena.requiredBadge ? String(arena.requiredBadge) : '';
    const missingBadge = !!(reqBadgeKey && !game.hasBadge(reqBadgeKey));
    const reqZoneId = Number(arena.requiredZone);
    const missingZoneMastery = Number.isFinite(reqZoneId) && reqZoneId > 0
      && typeof game.isZoneMastered === 'function'
      && !game.isZoneMastered(reqZoneId);
    let unlockStatus = game.t('arenaUi.unlockUnlocked');
    if (!unlocked) {
      const lockParts: string[] = [];
      if (missingBadge) {
        const badgeTalent = (ACCOUNT_TALENTS as Record<string, Record<string, unknown>>)[reqBadgeKey];
        const badgeName = badgeTalent
          ? game.getLocalizedAccountTalentName(reqBadgeKey, String(badgeTalent.name))
          : reqBadgeKey;
        lockParts.push(game.t('arenaUi.unlockRequiresBadge', { badge: badgeName }));
      }
      if (missingZoneMastery) {
        lockParts.push(game.t('arenaUi.unlockRequiresZoneMastery', { zone: requiredZoneName }));
      }
      unlockStatus = lockParts.length
        ? lockParts.join(' · ')
        : game.t('arenaUi.unlockRequires', { zone: requiredZoneName });
    }
    const cardClass = `upgrade-card${completed ? ' arena-completed' : ''}${!unlocked ? ' arena-locked' : ''}`;
    arenasHtml += `
            <div class="${cardClass}">
            <div class="upgrade-title">${asDisplayText(arena.name)}</div>
            <div class="upgrade-description">
                <div class="arena-champion-row">
                    ${championSpriteUrl
                      ? `<img src="${asDisplayText(championSpriteUrl)}" class="arena-champion-sprite" alt="${asDisplayText(arena.championName)}" onerror="this.remove();">`
                      : ''}
                    <span><strong>${game.t('arenaUi.championLabel')}</strong> ${asDisplayText(arena.championName)}</span>
                </div>
            </div>
            <div class="arena-reward-box">
                <div class="arena-reward-title arena-reward-title-with-badge">${rewardBadgeHtml}<span>${game.t('arenaUi.rewardLabel', { name: talentName })}</span></div>
                <div class="arena-reward-desc">${talentDesc}</div>
            </div>
            <div class="arena-unlock-status">
                ${unlockStatus}
            </div>
            <button class="upgrade-btn" 
                    data-action="startArena" data-arg="${arenaId}" 
                    ${!unlocked || completed ? 'disabled' : ''}>
                ${completed ? game.t('arenaUi.buttonBadgeOwned') : (unlocked ? game.t('arenaUi.buttonFight') : game.t('arenaUi.buttonLocked'))}
            </button>
            </div>
        `;
  });

  const eliteArenaId = game.getEliteFourArenaIdForCurrentRegion();
  const eliteFourTrainers = buildEliteFourTrainerPreviews(game, eliteArenaId);

  return {
    ui: buildArenaPanelUi(game),
    trainerCardTitle,
    badgesHtml,
    arenasHtml,
    eliteFourHtml: buildEliteFourPanelHtml(game),
    eliteFourTrainers,
  };
}

export function bindArenaBadgeTooltips(container: HTMLElement, game: GameRuntime): void {
  if (!game || typeof game.scheduleTooltip !== 'function') return;
  container.querySelectorAll('[data-tooltip-title]').forEach((node) => {
    const title = node.getAttribute('data-tooltip-title') || '';
    const desc = node.getAttribute('data-tooltip-desc') || '';
    node.addEventListener('mouseenter', (ev) => game.scheduleTooltip(ev, title, desc));
    node.addEventListener('mouseleave', () => { if (typeof game.hideTooltip === 'function') game.hideTooltip(); });
  });
}

let lastArenaSnapshot: ArenaSnapshot | null = null;

/** @internal Vitest only */
export function resetArenaSnapshotDedupForTests(): void {
  lastArenaSnapshot = null;
}

export function notifyArenaChanged(game: GameRuntime): void {
  const arena = buildArenaPanelSnapshot(game);
  if (lastArenaSnapshot && !arenaSnapshotWouldChange(lastArenaSnapshot, arena)) return;
  lastArenaSnapshot = arena;
  publish({ type: Evt.ARENA_CHANGED, arena });
}
